export function buildTimelinePromptIndex(epoch, rows, options = {}) {
    if (options.includeItems) {
        const candidates = rows.filter((row) => row.item.type === "user_message" &&
            (options.cursor === undefined || row.seq > options.cursor));
        const prompts = [];
        let bytes = 0;
        for (const row of candidates) {
            const size = Buffer.byteLength(JSON.stringify(row.item));
            if (prompts.length >= 50 || (prompts.length > 0 && bytes + Math.min(size, 65536) > 262144)) break;
            prompts.push({seq: row.seq, timestamp: row.timestamp, preview: promptPreview(row.item.text),
                ...(size <= 65536 ? {item: {type: row.item.type, text: row.item.text,
                    ...(row.item.messageId !== undefined ? {messageId: row.item.messageId} : {}),
                    ...(row.item.clientMessageId !== undefined ? {clientMessageId: row.item.clientMessageId} : {})}} : {})});
            bytes += Math.min(size, 65536);
        }
        return {epoch, prompts, nextCursor: prompts.length < candidates.length ? prompts[prompts.length - 1].seq : null};
    }

